package httpapi

import (
	"context"
	"errors"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/sanskarIN/stockpilot/internal/auth"
	"github.com/sanskarIN/stockpilot/internal/domain"
	"github.com/sanskarIN/stockpilot/internal/repository"
)

type fakeStore struct{createdProduct domain.Product;movementActor string;transferActor string;createdOrder domain.PurchaseOrder;receiptActor string;reorderSuggestions []domain.ReorderSuggestion;valuation domain.InventoryValuationReport;auditEvents []domain.AuditEvent;updatedOrder domain.PurchaseOrder}
func(f *fakeStore)CreateCategory(context.Context,domain.Category)error{return nil};func(f *fakeStore)ListCategories(context.Context)([]domain.Category,error){return nil,nil};func(f *fakeStore)CreateSupplier(context.Context,domain.Supplier)error{return nil};func(f *fakeStore)ListSuppliers(context.Context,bool)([]domain.Supplier,error){return nil,nil};func(f *fakeStore)CreateProduct(_ context.Context,p domain.Product)error{f.createdProduct=p;return nil};func(f *fakeStore)UpdateProduct(context.Context,domain.Product)error{return nil};func(f *fakeStore)GetProduct(_ context.Context,id string)(domain.Product,error){if f.createdProduct.ID==id{return f.createdProduct,nil};return domain.Product{},domain.ErrNotFound};func(f *fakeStore)GetProductByBarcode(_ context.Context,barcode string)(domain.Product,error){if f.createdProduct.Barcode!=""&&f.createdProduct.Barcode==barcode{return f.createdProduct,nil};return domain.Product{},domain.ErrNotFound};func(f *fakeStore)ListProducts(context.Context,repository.ProductFilter)([]domain.Product,error){return nil,nil};func(f *fakeStore)CreateWarehouse(context.Context,domain.Warehouse)error{return nil};func(f *fakeStore)ListWarehouses(context.Context,bool)([]domain.Warehouse,error){return nil,nil};func(f *fakeStore)CreateLocation(context.Context,domain.Location)error{return nil};func(f *fakeStore)ListLocations(context.Context,string,bool)([]domain.Location,error){return nil,nil};func(f *fakeStore)CreateLot(context.Context,domain.Lot)error{return nil};func(f *fakeStore)ListLots(context.Context,string,int)([]domain.Lot,error){return nil,nil};func(f *fakeStore)ApplyMovement(_ context.Context,m domain.StockMovement)(domain.StockBalance,error){f.movementActor=m.ActorID;return domain.StockBalance{},nil};func(f *fakeStore)Transfer(_ context.Context,r domain.TransferRequest)error{f.transferActor=r.ActorID;return nil};func(f *fakeStore)GetBalance(context.Context,string,string,string)(domain.StockBalance,error){return domain.StockBalance{},nil};func(f *fakeStore)ListLowStock(context.Context,int)([]domain.StockBalance,error){return nil,nil};func(f *fakeStore)ListReorderSuggestions(context.Context,int)([]domain.ReorderSuggestion,error){return f.reorderSuggestions,nil};func(f *fakeStore)GetInventoryValuation(context.Context,int)(domain.InventoryValuationReport,error){return f.valuation,nil};func(f *fakeStore)CreateOrder(_ context.Context,o domain.PurchaseOrder)error{f.createdOrder=o;return nil};func(f *fakeStore)UpdateOrder(_ context.Context,o domain.PurchaseOrder)error{f.updatedOrder=o;return nil};func(f *fakeStore)GetOrder(_ context.Context,id string)(domain.PurchaseOrder,error){if f.updatedOrder.ID==id{return f.updatedOrder,nil};return domain.PurchaseOrder{ID:id,Status:domain.PurchaseOrderDraft,Lines:[]domain.PurchaseOrderLine{{ID:"pol_1",PurchaseOrderID:id,ProductID:"prd_1",Quantity:5}}},nil};func(f *fakeStore)ListOrders(context.Context,domain.PurchaseOrderStatus,int,int)([]domain.PurchaseOrder,error){return nil,nil};func(f *fakeStore)ReceiveLine(_ context.Context,_ string,_ string,_ int64,_ string,_ string,actorID string)error{f.receiptActor=actorID;return nil};func(f *fakeStore)ReceiveLineWithNewLot(_ context.Context,_ string,_ string,_ int64,_ string,_ domain.Lot,actorID string)error{f.receiptActor=actorID;return nil};func(f *fakeStore)UpdateOrderStatus(context.Context,string,domain.PurchaseOrderStatus,string)error{return nil};func(f *fakeStore)AppendAuditEvent(_ context.Context,e domain.AuditEvent)error{f.auditEvents=append(f.auditEvents,e);return nil};func(f *fakeStore)ListAuditEvents(context.Context,domain.AuditFilter)([]domain.AuditEvent,error){return f.auditEvents,nil}

func TestHealthEndpoint(t *testing.T){store:=&fakeStore{};handler:=New(store,store,store,func(context.Context)error{return nil},nil,nil);recorder:=httptest.NewRecorder();handler.ServeHTTP(recorder,httptest.NewRequest(http.MethodGet,"/healthz",nil));if recorder.Code!=http.StatusOK{t.Fatalf("status=%d",recorder.Code)};if !strings.Contains(recorder.Body.String(),`"status":"ok"`){t.Fatalf("body=%q",recorder.Body.String())};if recorder.Header().Get("X-Request-ID")==""{t.Fatal("X-Request-ID missing")}}
func TestReadyEndpointReportsDependencyFailure(t *testing.T){store:=&fakeStore{};handler:=New(store,store,store,func(context.Context)error{return errors.New("database unavailable")},nil,nil);recorder:=httptest.NewRecorder();handler.ServeHTTP(recorder,httptest.NewRequest(http.MethodGet,"/readyz",nil));if recorder.Code!=http.StatusServiceUnavailable{t.Fatalf("status=%d",recorder.Code)}}
func TestCreateProductGeneratesIDAndDefaultsCurrency(t *testing.T){store:=&fakeStore{};handler:=New(store,store,store,func(context.Context)error{return nil},nil,nil);recorder:=httptest.NewRecorder();handler.ServeHTTP(recorder,httptest.NewRequest(http.MethodPost,"/api/v1/products",strings.NewReader(`{"sku":"SKU-1","name":"Widget","unit":"piece","active":true}`)));if recorder.Code!=http.StatusCreated{t.Fatalf("status=%d",recorder.Code)};if store.createdProduct.ID==""||store.createdProduct.Currency!="INR"{t.Fatalf("product=%+v",store.createdProduct)};if len(store.auditEvents)!=0{t.Fatalf("unexpected audit without insights: %d",len(store.auditEvents))}}
func TestInventoryMutationUsesAuthenticatedActor(t *testing.T){store:=&fakeStore{};handler:=NewCore(store,store,store,func(context.Context)error{return nil});request:=authenticatedRequest(http.MethodPost,"/api/v1/inventory/movements",`{"productId":"prd_1","locationId":"loc_1","type":"stock_in","quantityDelta":5,"actorId":"usr_spoofed"}`);recorder:=httptest.NewRecorder();handler.ServeHTTP(recorder,request);if recorder.Code!=http.StatusCreated||store.movementActor!="usr_session"{t.Fatalf("status=%d actor=%q",recorder.Code,store.movementActor)}}
func TestCreateOrderUsesAuthenticatedActorAndGeneratesIDs(t *testing.T){store:=&fakeStore{};handler:=NewCore(store,store,store,func(context.Context)error{return nil});request:=authenticatedRequest(http.MethodPost,"/api/v1/orders",`{"number":"PO-100","supplierId":"sup_1","warehouseId":"wh_1","status":"draft","currency":"INR","lines":[{"productId":"prd_1","quantity":5,"received":0,"unitCostMinor":2500}]}`);recorder:=httptest.NewRecorder();handler.ServeHTTP(recorder,request);if recorder.Code!=http.StatusCreated||!strings.HasPrefix(store.createdOrder.Lines[0].ID,"pol_"){t.Fatalf("status=%d order=%+v",recorder.Code,store.createdOrder)}}
func TestUpdateOrderGeneratesMissingLineIDsAndUsesAuthenticatedActor(t *testing.T){store:=&fakeStore{updatedOrder:domain.PurchaseOrder{ID:"po_1",Status:domain.PurchaseOrderDraft,Lines:[]domain.PurchaseOrderLine{{ID:"pol_existing",PurchaseOrderID:"po_1",ProductID:"prd_1",Quantity:3}}}};handler:=NewCore(store,store,store,func(context.Context)error{return nil},WithInsights(nil,store));request:=authenticatedRequest(http.MethodPut,"/api/v1/orders/po_1",`{"number":"PO-1","supplierId":"sup_1","warehouseId":"wh_1","status":"draft","currency":"INR","lines":[{"productId":"prd_1","quantity":3,"received":0,"unitCostMinor":100},{"productId":"prd_2","quantity":2,"received":0,"unitCostMinor":200}]}`);recorder:=httptest.NewRecorder();handler.ServeHTTP(recorder,request);if recorder.Code!=http.StatusOK{t.Fatalf("status=%d body=%s",recorder.Code,recorder.Body.String())};if len(store.updatedOrder.Lines)!=2||store.updatedOrder.Lines[1].ID==""{t.Fatalf("updated order=%+v",store.updatedOrder)};if len(store.auditEvents)==0||store.auditEvents[len(store.auditEvents)-1].Action!="purchase_order.updated"{t.Fatalf("audit=%+v",store.auditEvents)}}
func TestAuditRecorderCapturesRequestIDAndActor(t *testing.T){store:=&fakeStore{};handler:=NewCore(store,store,store,func(context.Context)error{return nil},WithInsights(nil,store));request:=authenticatedRequest(http.MethodPost,"/api/v1/products",`{"sku":"SKU-9","name":"Audit Widget","unit":"piece","active":true}`);request=request.WithContext(context.WithValue(request.Context(),requestIDContextKey{},"req_test"));recorder:=httptest.NewRecorder();handler.ServeHTTP(recorder,request);if len(store.auditEvents)==0||store.auditEvents[0].RequestID!="req_test"||store.auditEvents[0].ActorID!="usr_session"{t.Fatalf("audit=%+v",store.auditEvents)}}
func authenticatedRequest(method,target,body string)*http.Request{request:=httptest.NewRequest(method,target,strings.NewReader(body));principal:=auth.Principal{User:domain.User{ID:"usr_session",Role:domain.RoleAdmin,Active:true}};return request.WithContext(context.WithValue(request.Context(),principalContextKey{},principal))}
